mapper.update:
UPDATE notification_send_history SET status=#{retryWaitingStatus}, next_retry_at=#{now}, locked_at=NULL,
    locked_by=NULL, error_type=#{errorType}, error_message=#{errorMessage}, updated_at=CURRENT_TIMESTAMP(3)
WHERE status=#{sendingStatus} AND locked_at < #{staleBefore}

mapper.select:
SELECT id FROM notification_send_history WHERE status IN (#{pendingStatus}, #{retryWaitingStatus})
  AND (next_retry_at IS NULL OR next_retry_at <= #{now}) AND attempt_count < max_attempts
ORDER BY COALESCE(next_retry_at, created_at), id LIMIT #{limit}

mapper.update:
UPDATE notification_send_history SET status=#{successStatus}, attempt_count=attempt_count+1, next_retry_at=NULL,
    locked_at=NULL, locked_by=NULL, error_type=NULL, error_message=NULL, provider_status_code=#{providerStatusCode},
    provider_message=#{providerMessage}, sent_at=CURRENT_TIMESTAMP(3), updated_at=CURRENT_TIMESTAMP(3) WHERE id=#{id}

UPDATE notification_send_history SET status=#{retryWaitingStatus}, attempt_count=attempt_count+1,
    next_retry_at=#{nextRetryAt}, locked_at=NULL, locked_by=NULL, error_type=#{errorType}, error_message=#{errorMessage},
    provider_status_code=#{providerStatusCode}, provider_message=#{providerMessage}, updated_at=CURRENT_TIMESTAMP(3) WHERE id=#{id}

mapper.select:
SELECT h.status AS status, COUNT(*) AS total FROM notification_send_history h
h.created_at >= #{startTime} AND h.created_at < #{endTime}
GROUP BY h.status

SELECT DATE(h.created_at) AS bucket_date, h.status AS status, COUNT(*) AS total FROM notification_send_history h
h.created_at >= #{startTime} AND h.created_at < #{endTime}
GROUP BY DATE(h.created_at), h.status ORDER BY bucket_date ASC, status ASC
